import styled from '@emotion/styled';
import {
  COMING_SOON_TYPE,
  NO_DATA_TYPE,
  SEARCH_EMPTY_TYPE,
} from 'pages/trainingHub/constants';
import { EmptyType } from 'pages/trainingHub/domain';

export const StyledEmptyContainer = styled.div(
  {
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'center',
    flex: 1,
  },
  ({ $type }: { $type: EmptyType }) => ({
    height: $type === COMING_SOON_TYPE ? '334px' : '100%',
  }),
);

export const StyledEmptyIcon = styled.img(
  {
    width: '128px',
    height: '128px',
  },
  ({ $type }: { $type: EmptyType }) => ({
    width: $type === SEARCH_EMPTY_TYPE && '200px',
    height: $type === SEARCH_EMPTY_TYPE && '200px',
  }),
);

export const StyledEmptyTitle = styled.h1(
  {
    fontFamily: 'Barlow',
    fontWeight: 600,
    fontSize: '24px',
    color: '#141414',
    lineHeight: '120%',
    letterSpacing: '0px',
    textAlign: 'center',
    margin: '10px 0 0 0',
  },
  ({ $hasData }: { $hasData: boolean }) => ({
    display: $hasData ? 'block' : 'none',
  }),
);

export const StyledEmptyDescription = styled.p(
  {
    fontFamily: 'Work Sans',
    fontWeight: 400,
    fontSize: '14px',
    color: '#5C5C5C',
    lineHeight: '140%',
    letterSpacing: '0px',
    textAlign: 'center',
    maxWidth: '256px',
    margin: '6px 0',
  },
  ({ $hasData, $type }: { $hasData: boolean; $type: EmptyType }) => ({
    display: $hasData ? 'block' : 'none',
    margin: $type === NO_DATA_TYPE && '16px',
    padding: $type === SEARCH_EMPTY_TYPE && '0 16px',
  }),
);
